-- Phase 16: Barangay Mapping (spatial layer foundation).
-- Adds a reference table of Caloocan's 188 barangays (name/PSGC code/centroid),
-- matched by name against the free-text `barangay` column already used across
-- residents/housing_units/urban_projects/infrastructure_records/zoning_clearances.
-- Boundary polygons live in assets/geojson/caloocan-barangays.geojson (not in MySQL)
-- and are matched to this table client-side by `psgc_code`.
-- Also adds optional coordinates to housing_units so awarded housing projects can be
-- placed as map markers; existing rows are unaffected (both columns default NULL).

CREATE TABLE IF NOT EXISTS `barangays` (
  `barangay_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `psgc_code` VARCHAR(20) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `district` VARCHAR(50) NULL,
  `centroid_lat` DECIMAL(10,8) NULL,
  `centroid_lng` DECIMAL(11,8) NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`barangay_id`),
  UNIQUE KEY `uniq_barangay_psgc` (`psgc_code`),
  UNIQUE KEY `uniq_barangay_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE `housing_units`
  ADD COLUMN `latitude` DECIMAL(10,8) NULL AFTER `street_address`,
  ADD COLUMN `longitude` DECIMAL(11,8) NULL AFTER `latitude`;

-- Seed: 188 barangays, name + PSGC code from PSA PSGC (Dec 2023), centroid computed
-- from the boundary polygons in assets/geojson/caloocan-barangays.geojson.
-- District is left NULL; this source does not carry a legislative-district field.
